import{z as s,x as n,o as t,c as d,q as i,j as o,D as e,d as l,s as r,S as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"W4A8 / W4A16","description":"","frontmatter":{"title":"W4A8 / W4A16","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/w4a16.md","filePath":"llm/w4a16.md","lastUpdated":1791413859000}'),p={name:"llm/w4a16.md"};function b(W,a,B,m,h,c){const A=n("Mermaid");return t(),d("div",null,[a[2]||(a[2]=i('<h1 id="w4a8-w4a16" tabindex="-1">W4A8 / W4A16 <a class="header-anchor" href="#w4a8-w4a16" aria-label="Permalink to &quot;W4A8 / W4A16&quot;">​</a></h1><div class="epigraph"><p>4-bit 权重减的是每步要扫过的字节；激活仍用 16-bit 时，decode 吃带宽红利。若再把激活打到 8-bit，是在同一套粗权重上叠加第二条量化噪声，换的是 prefill 的算术密度。</p><footer>—— 对照 Frantar et al., GPTQ, ICLR 2023；Lin et al., AWQ, MLSys 2024；与 W8A8 的激活精度权衡</footer></div><p>W4A16 是端侧与单卡服务里最常见的权重量化落点：权重每参数 4 bit，激活与矩阵乘累加仍用 FP16 或 BF16。<a href="/llm/gptq">GPTQ</a> 与 <a href="/llm/awq">AWQ</a> 的论文主线都在这条线上——它们要回答的是「4-bit 格子怎么选才不把层输出打崩」，不是「INT8 Tensor Core 怎么喂饱」。W4A8 把激活再降到 8-bit，试图同时拿走权重带宽与 8-bit 算术，误差预算却变成两份相乘。本篇把 W4A16 写成默认，把 W4A8 写成加激活量化之后的权衡，并与 <a href="/llm/w8a8">W8A8</a> 对照：真正在换的是<strong>激活精度</strong>，不是「4 比 8 更强」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Decode 阶段查询极短，每步几乎要把全部权重从 HBM 搬进片上，见 <a href="/llm/decode-memory-wall">Decode 的显存墙</a>。FP16 的 70B 仅权重就超过 100GB 量级；4-bit 后体积大约四分之一，单卡容量与加载带宽同时松绑。激活在 batch=1 时只是一行，压不压 8-bit 对加载项几乎看不见，却要为每个 token 估尺度、插量化核。于是小 batch 生成的理性默认是：<strong>狠压权重、放过激活</strong>。这就是 W4A16。</p><p><span class="marginnote">术语翻译：W4A16 读作「权重 4 比特、激活 16 比特」——W 是 Weight（权重），A 是 Activation（激活）。它只回答「每层乘法的两个操作数各用几位存」，与用哪种算法量化（GPTQ、AWQ、RTN）无关；同一张 4-bit 格子可以由三种算法去填。</span></p><p><span class="marginnote">数字实例：70B 参数的模型，FP16 权重是 \\(70 \\times 2 = 140\\) GB，一张 80GB 卡根本放不下；打成 group_size=128 的 4-bit 后约 \\(70 \\times 0.5 = 35\\) GB，再加约 3% 的尺度元数据，单卡装得下，decode 每步要搬的字节也少约 4 倍——这就是带宽红利的直接来源。</span></p><p>困难在 4-bit 本身。均匀 16 档格子相对半精度是 4 倍信息损失，RTN 会在显著通道上放大误差。GPTQ 用校准 Hessian 补偿，AWQ 用激活感知缩放保护显著列，<a href="/llm/other-ptq">AutoRound</a> 改取整边。它们共享前提：乘法的另一侧足够精细，能量得起权重的离散误差。一旦激活也量化，这个前提要重验。</p><h3 id="w4a8-不是-w4a16-的免费升级" tabindex="-1">W4A8 不是 W4A16 的免费升级 <a class="header-anchor" href="#w4a8-不是-w4a16-的免费升级" aria-label="Permalink to &quot;W4A8 不是 W4A16 的免费升级&quot;">​</a></h3><p>W4A8 看起来像「两点都省」。权重仍 4-bit，激活 8-bit，prefill 的 \\(X\\) 可以走更窄的总线，部分硬件还提供 INT4×INT8 或「4-bit 权重解到寄存器再与 INT8 激活乘」。精度上却是 \\((W+E_w)(X+E_x)=WX+E_wX+WE_x+E_wE_x\\)。W4A16 只有 \\(E_wX\\)；W8A8 的 \\(E_w\\)、\\(E_x\\) 都较小。W4A8 让较大的 \\(E_w\\) 去乘已经带噪的 \\(X\\)，交叉项在深层残差里累积。没有新的补偿算法，只是把两种 PTQ 叠起来，生成质量往往先于吞吐到达产品线。</p><p><span class="marginnote">服务广告里的「4-bit 推理」多数指 W4A16。KV 仍可能是 16-bit 或另做 8-bit。读基准时要拆三项：权重点型、激活点型、KV 点型。缺任何一项，tokens/s 都无法复现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>W4A16 的离线步骤：用校准文本缓存各层输入，按 GPTQ / AWQ / AutoRound 之一（或级联）得到分组 4-bit 权重与尺度；推理核按组加载整数，在片上乘尺度得到与 FP16 激活相乘的有效权重，或使用硬件支持的 4-bit Tensor Core 路径。分组大小（如 128）是质量与元数据的折中：组越大越省尺度，越容易被组内动态范围伤害。注意力输出投影、MLP 门控、<code>lm_head</code> 是否留 8-bit，属于实现契约，换会改困惑度。</p><p>W4A8 在此之上对 \\(X\\) 做在线 8-bit。若激活仍有通道异常值，需要先做 SmoothQuant 一类迁移，再量化激活；权重侧的 4-bit 是在<strong>已经乘过 \\(s\\)</strong> 的 \\(W&#39;\\) 上打的，顺序不能反。另一种做法是混合：prefill 用 W4A8 或 W8A8，decode 切回 W4A16，要求两套核、同一份权重能被两种反量化路径消费，工程成本高于单一 W4A16。</p>',14)),(t(),o(E,null,{default:e(()=>[r(A,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20w4a16%20%5B%22W4A16%22%5D%0A%20%20%20%20W4%5B%224-bit%20W%22%5D%20--%3E%20M16%5B%22%E4%B9%98%20FP16%2FBF16%20%E6%BF%80%E6%B4%BB%22%5D%0A%20%20%20%20A16%5B%2216-bit%20X%22%5D%20--%3E%20M16%0A%20%20end%0A%20%20subgraph%20w4a8%20%5B%22W4A8%22%5D%0A%20%20%20%20W4b%5B%224-bit%20W%22%5D%20--%3E%20M8%5B%22%E4%B9%98%208-bit%20%E6%BF%80%E6%B4%BB%22%5D%0A%20%20%20%20A8%5B%22INT8%2FFP8%20X%22%5D%20--%3E%20M8%0A%20%20end%0A%20%20subgraph%20w8a8%20%5B%22W8A8%22%5D%0A%20%20%20%20W8%5B%228-bit%20W%22%5D%20--%3E%20M88%5B%22INT8%2FFP8%20GEMM%22%5D%0A%20%20%20%20A8b%5B%228-bit%20X%22%5D%20--%3E%20M88%0A%20%20end%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p>真正加速要求核按 4-bit 加载。先把全模型解成 FP16 再乘，只省磁盘与占用，decode 带宽与 FP16 相同。这是端侧演示里常见的假 4-bit。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="为何-decode-偏爱-16-bit-激活" tabindex="-1">为何 decode 偏爱 16-bit 激活 <a class="header-anchor" href="#为何-decode-偏爱-16-bit-激活" aria-label="Permalink to &quot;为何 decode 偏爱 16-bit 激活&quot;">​</a></h3><p>算术强度粗略是 \\(\\mathrm{FLOPs}/\\mathrm{Bytes}\\)。Decode 一步，FLOPs 与 \\(d_{\\mathrm{model}}\\) 成正比，Bytes 几乎等于权重体积。把权重从 16-bit 打到 4-bit，分母除以 4，强度上升，更接近算力屋顶——但通常仍远未打满 GPU 峰值，所以墙钟仍跟带宽走，加速接近体积比（再扣核开销）。激活 16-bit 在这一步的字节可以忽略。把激活改成 8-bit，分母几乎不变，分子若没有 INT4×INT8 的更高吞吐，墙钟不降，只多噪声。</p><p>Prefill 相反：\\(X\\) 的字节与 \\(n\\times d\\) 同阶，激活量化开始改变分母，8-bit GEMM 开始改变分子。W4A8 的合理舞台是「权重已经被 4-bit 绑死、又要打 prefill SLA」的节点，不是 batch=1 聊天。</p><p>权重误差 \\(E_w\\) 经激活放大。W4A16 里 \\(X\\) 精细，\\(E_wX\\) 就是 GPTQ 在最小化的对象。W4A8 里 \\(X\\) 已含 \\(E_x\\)，最小化 \\(\\|WX-\\hat{W}X_{\\mathrm{fp16}}\\|\\) 的校准<strong>对不准</strong>真实推理路径 \\(\\|WX-\\hat{W}X_{\\mathrm{int8}}\\|\\)。正确做法是校准循环里用量化后的激活往下一层送，与 GPTQ 逐层量化同一纪律，只是对象多了激活。许多「把 AWQ 权重接到 INT8 激活上」的失败，来自校准与推理路径不一致。</p><p>把 decode 与 prefill 放在同一个「搬多少字节、做多少算术」的账上，W4A16 与 W4A8 各自主场的分工就看清楚了：decode 的时间花在搬权重上，prefill 的时间花在算乘法上。</p>',7)),(t(),o(E,null,{default:e(()=>[r(A,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHASE%7B%22%E6%8E%A8%E7%90%86%E5%9C%A8%E5%93%AA%E4%B8%AA%E9%98%B6%E6%AE%B5%22%7D%0A%20%20PHASE%20--%3E%7C%22decode%EF%BC%9A%E4%B8%80%E6%AC%A1%E4%B8%80%E4%B8%AA%20token%22%7C%20BW%5B%22%E7%93%B6%E9%A2%88%E6%98%AF%E6%9D%83%E9%87%8D%E5%8A%A0%E8%BD%BD%E5%AD%97%E8%8A%82%22%5D%0A%20%20PHASE%20--%3E%7C%22prefill%EF%BC%9A%E9%95%BF%20prompt%20%E4%B8%80%E6%AC%A1%E7%AE%97%22%7C%20FLOP%5B%22%E7%93%B6%E9%A2%88%E6%98%AF%20GEMM%20%E7%AE%97%E6%9C%AF%22%5D%0A%20%20BW%20--%3E%20W16%5B%224-bit%20%E6%9D%83%E9%87%8D%E5%87%8F%204%20%E5%80%8D%E5%AD%97%E8%8A%82%22%5D%0A%20%20W16%20--%3E%20WIN16%5B%22W4A16%20%E7%9B%B4%E6%8E%A5%E6%8F%90%E9%80%9F%22%5D%0A%20%20BW%20--%3E%20X8%5B%22%E6%BF%80%E6%B4%BB%208-bit%20%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%87%8F%E5%AD%97%E8%8A%82%22%5D%0A%20%20X8%20--%3E%20LOSE%5B%22%E5%8F%AA%E6%B7%BB%E5%99%AA%E5%A3%B0%E3%80%81%E5%A2%99%E9%92%9F%E4%B8%8D%E9%99%8D%22%5D%0A%20%20FLOP%20--%3E%20GEMM%5B%228-bit%20GEMM%20%E6%8F%90%E7%AE%97%E6%9C%AF%E5%AF%86%E5%BA%A6%22%5D%0A%20%20GEMM%20--%3E%20WIN8%5B%22W4A8%20%E5%9C%A8%E8%BF%99%E9%87%8C%E6%89%8D%E6%9C%89%E6%94%B6%E7%9B%8A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p><span class="marginnote">直觉类比：decode 像小作坊每次只做一个零件，时间全花在去仓库取图纸的路上——把图纸印薄（权重 4-bit）直接省时间；把零件材质升级（激活 8-bit）对取图速度毫无帮助。prefill 像一次性收到一万张订单，时间花在车间加工上，这时升级机床（8-bit GEMM）才见效。</span></p><p><span class="marginnote">分组 4-bit 的尺度是 FP16 还是 FP8、是否对称，会改变反量化在寄存器里怎么做。W4A8 若用整数管道，尺度还要能和激活尺度融合成一次乘。格式细节属于核，不属于「W4」这个名字。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>4-bit 对嵌入与 lm_head 往往不值：词表宽、误差直接进 logits，常见做法是这两处留 8-bit 或 16-bit，体积增量相对 70B 可忽略。视觉-语言投影、MoE 路由门也是敏感点，AWQ 相对 GPTQ 更常被用来保护它们，因为不在校准句上做二阶过拟合。</p><p>W4A8 的硬件支持碎。有的 NPU 原生喜欢 INT8 激活配 INT8 或 INT4 权重；有的 GPU 上 INT4 核只为权重解码设计，激活仍要 FP16。没有核就不要为了表格里的 W4A8 去叠激活量化。FP8 激活配 4-bit 权重是另一条厂商路径，误差行为更接近「浮点激活略粗」，与 INT8 仿射不是同一套尺度算术，见 <a href="/llm/fp8-inference">FP8 推理</a>。</p><h3 id="与-qlora-的-4-bit-不要互换" tabindex="-1">与 QLoRA 的 4-bit 不要互换 <a class="header-anchor" href="#与-qlora-的-4-bit-不要互换" aria-label="Permalink to &quot;与 QLoRA 的 4-bit 不要互换&quot;">​</a></h3><p><a href="/llm/qlora">QLoRA</a> 的 NF4 是训练期存储码本，前向要反量化到 16-bit 再乘。GPTQ/AWQ 的 INT4 是推理期打包。把 QLoRA 检查点当 W4A16 服务，或把 GPTQ 权重当 QLoRA 基座接着训，都会在反量化表上对错。W4A16 是部署配方；QLoRA 是压缩微调配方，见 <a href="/llm/qlora-as-compression">QLoRA 作为压缩微调</a>。</p><p><span class="marginnote">同一 4-bit 文件在 llama.cpp、AutoGPTQ、AWQ 容器之间不能只改后缀。group_size、zero_point、是否 <code>desc_act</code> 重排，错一位就是通道错位，表现像随机初始化而不是「略掉点」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>W4A16 狠压权重、激活保持 16-bit，匹配小 batch decode 的带宽墙；GPTQ/AWQ/AutoRound 都主要服务这条线。</li><li>W4A8 再量化激活，交叉误差更大，校准必须沿量化激活路径走；收益主要在 prefill 与大 batch。</li><li>W8A8 与 W4A16 的核心差别是激活精度：前者换算术密度，后者换权重加载。</li><li>假 4-bit（解回 FP16 再乘）只省占用，不省 decode 带宽。</li><li>嵌入、lm_head、多模态投影常需更高比特；核与分组契约决定能否复现数字。</li><li>训练用 NF4 与推理用 INT4 不是同一检查点。</li><li>出处：Frantar et al., <em>GPTQ</em>, ICLR 2023；Lin et al., <em>AWQ</em>, MLSys 2024。W8A8 对照 Xiao et al., <em>SmoothQuant</em>, ICML 2023。</li></ul>',10))])}const T=s(p,[["render",b]]);export{P as __pageData,T as default};
